use desafio::dobra;

#[test]
fn testa_a_dobra_do_placar_de_dez() {
    let mut placar = 10;
    let novo = dobra(&mut placar);
    assert_eq!(novo, 20);
    assert_eq!(placar, 20);
}

#[test]
fn testa_a_dobra_do_placar_de_dois() {
    let mut placar = 2;
    let novo = dobra(&mut placar);
    assert_eq!(novo, 4);
    assert_eq!(placar, 4);
}
